task:
Was macht die folgende XQuery-Deklaration?

declare function local:person-name($key as xs:string) as xs:string? {
  let $person := doc(concat('/db/apps/WeGA-WebApp/data/persons/', $key, '.xml'))
  return $person//tei:persName[@type='reg']/string()
};

Was ist der Unterschied zwischen diesen beiden Deklarationen?

module namespace app="http://xquery.weber-gesamtausgabe.de/modules/app";

import module namespace wega-util="http://xquery.weber-gesamtausgabe.de/modules/wega-util"
  at "wega-util.xqm";

Schreibe eine eXist-db XQuery-Funktion, die:
1. Einen 'id'-Parameter liest (Fallback: '')
2. Das Dokument lädt: doc('/db/data/' || $id || '.xml')
3. Den normierten Personennamen (tei:persName[@type='reg']) holt
4. Als JSON zurückgibt: { "name": "..." }

Nutze: response:set-header(), serialize(), map{}

solution:
declare namespace tei="http://www.tei-c.org/ns/1.0";

let $id := request:get-parameter('id', '')
let $doc := doc('/db/data/' || $id || '.xml')
let $name := $doc//tei:persName[@type='reg']/string()
let $_ := response:set-header('Content-Type', 'application/json')
return serialize(
  map { 'name': $name },
  map { 'method': 'json' }
)

