declare namespace tei="http://www.tei-c.org/ns/1.0";

declare function api:document-meta($id as xs:string) as map(*) {
  let $doc := doc('/db/apps/WeGA-data/' || $id || '.xml')
  let $title := $doc//tei:title[@level='a']/string()
  let $date := $doc//tei:correspAction[@type='sent']/tei:date/@when/string()
  let $sender := $doc//tei:correspAction[@type='sent']//tei:persName/string()
  return map {
    'id': $id,
    'title': $title,
    'date': $date,
    'sender': $sender
  }
};

module namespace local="http://wega-learn.example/local";
declare namespace tei="http://www.tei-c.org/ns/1.0";

(:~
 : Gibt den normierten Namen einer tei:persName-Gruppe zurück.
 : @param $persName das persName-Element
 : @return normierter Namens-String
 :)
declare function local:format-name($persName as element()) as xs:string {
  if ($persName[@type='reg'])
  then string($persName[@type='reg'])
  else string($persName[1])
};

(:~
 : Gibt eine Zusammenfassung eines Briefes als map zurück.
 : @param $id die WeGA-ID des Briefes (z.B. A040001)
 : @return map mit id, date, sender
 :)
declare function local:letter-summary($id as xs:string) as map(*) {
  let $doc := doc('/db/apps/WeGA-data/' || $id || '.xml')
  let $date := $doc//tei:correspAction[@type='sent']/tei:date/@when/string()
  let $sender := $doc//tei:correspAction[@type='sent']//tei:persName[1]
  return map {
    'id': $id,
    'date': $date,
    'sender': local:format-name($sender)
  }
};
